// src/capture/llm.ts

import { randomUUID } from "node:crypto";
import type {
  ExtensionAPI,
  MessageStartEvent,
  MessageUpdateEvent,
  MessageEndEvent,
  AfterProviderResponseEvent,
} from "@earendil-works/pi-coding-agent";
import type { AssistantMessage } from "@earendil-works/pi-ai";
import type { Telemetry } from "../state.ts";
import { guard } from "../state.ts";

interface InFlightRequest {
  requestId: string;
  startMs: number;
  firstUpdateMs: number | null;
  signature: string;
  turnId: string;
}

const inFlightRequests = new Map<string, InFlightRequest>();

function getMessageSignature(message: AssistantMessage): string {
  const parts = [
    message.provider ?? "",
    message.model ?? "",
    message.api ?? "",
    String(message.timestamp ?? ""),
    message.responseId ?? "",
  ];
  return parts.join("|");
}

export function registerLlmCapture(pi: ExtensionAPI, t: Telemetry): void {
  pi.on("message_start", async (event: MessageStartEvent) => {
    guard(t, () => {
      const message = event.message as AssistantMessage;
      if (message.role !== "assistant") return;
      const { sessionId, runId, turnId } = t.state.correlation();
      if (!sessionId || !turnId) return;

      const requestId = randomUUID();
      const now = t.now();
      const signature = getMessageSignature(message);

      const existing = inFlightRequests.get(signature);
      if (existing) {
        // Should not happen normally; clean up stale entry.
        inFlightRequests.delete(signature);
      }

      const inFlight: InFlightRequest = {
        requestId,
        startMs: now,
        firstUpdateMs: null,
        signature,
        turnId,
      };
      inFlightRequests.set(signature, inFlight);

      t.enqueue(
        `INSERT INTO llm_requests (
          request_id, turn_id, run_id, session_id, provider, model,
          started_unix_ms, ttft_ms, stream_ms, duration_ms,
          input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
          cost_total_usd, stop_reason, http_status, retry_after_ms
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          requestId, turnId, runId, sessionId,
          message.provider ?? null, message.model ?? null,
          now, null, null, null,
          null, null, null, null,
          null, null, null, null,
        ],
      );
    });
  });

  pi.on("message_update", async (event: MessageUpdateEvent) => {
    guard(t, () => {
      const message = event.message as AssistantMessage;
      if (message.role !== "assistant") return;
      const signature = getMessageSignature(message);
      const req = inFlightRequests.get(signature);
      if (!req) return;

      const now = t.now();
      if (req.firstUpdateMs === null) {
        req.firstUpdateMs = now;
        const ttftMs = now - req.startMs;
        t.enqueue(
          "UPDATE llm_requests SET ttft_ms = ? WHERE request_id = ?",
          [ttftMs, req.requestId],
        );
      }
    });
  });

  pi.on("message_end", async (event: MessageEndEvent) => {
    guard(t, () => {
      const message = event.message as AssistantMessage;
      if (message.role !== "assistant") return;
      const signature = getMessageSignature(message);
      const req = inFlightRequests.get(signature);
      if (!req) return;

      const now = t.now();
      const durationMs = now - req.startMs;
      const streamMs = req.firstUpdateMs !== null ? now - req.firstUpdateMs : null;

      const usage = message.usage;
      const cost = usage?.cost;

      t.enqueue(
        `UPDATE llm_requests SET
          duration_ms = ?,
          stream_ms = ?,
          input_tokens = ?,
          output_tokens = ?,
          cache_read_tokens = ?,
          cache_write_tokens = ?,
          cost_total_usd = ?,
          stop_reason = ?
        WHERE request_id = ?`,
        [
          durationMs,
          streamMs,
          usage?.input ?? null,
          usage?.output ?? null,
          usage?.cacheRead ?? null,
          usage?.cacheWrite ?? null,
          cost?.total ?? null,
          message.stopReason ?? null,
          req.requestId,
        ],
      );

      inFlightRequests.delete(signature);
    });
  });

  pi.on("after_provider_response", async (event: AfterProviderResponseEvent) => {
    guard(t, () => {
      const { turnId } = t.state.correlation();
      if (!turnId) return;

      // Find the most recent in-flight request for this turn.
      let target: InFlightRequest | undefined;
      for (const req of inFlightRequests.values()) {
        if (req.turnId === turnId) {
          if (!target || req.startMs > target.startMs) {
            target = req;
          }
        }
      }

      const retryAfterHeader = event.headers["retry-after"] ?? event.headers["Retry-After"];
      let retryAfterMs: number | null = null;
      if (retryAfterHeader) {
        const parsed = parseInt(retryAfterHeader, 10);
        if (!Number.isNaN(parsed)) {
          retryAfterMs = parsed * 1000;
        }
      }

      if (target) {
        t.enqueue(
          "UPDATE llm_requests SET http_status = ?, retry_after_ms = ? WHERE request_id = ?",
          [event.status, retryAfterMs, target.requestId],
        );
      }
      // If no in-flight request, the status is for the next request; ignore for now.
    });
  });
}
```

